css:
.print-format { orientation: Landscape; }
.lot-cloth-program { box-sizing: border-box; color: #111; font-family: Arial, sans-serif; font-size: 12px; margin: 0 auto; padding: 8px 14px 12px; width: 100%; }
.program-title { border-bottom: 2px solid #111; font-size: 20px; font-weight: 700; margin: 0 0 12px; padding-bottom: 7px; text-align: center; }
.program-identifiers { border-collapse: collapse; margin: 0 0 12px; width: 100%; }
.program-identifiers td { border: 0; font-size: 15px; font-weight: 700; padding: 0 4px; width: 50%; }
.program-identifiers .item { text-align: right; }
.program-meta { border-collapse: collapse; margin: 0 0 18px; table-layout: fixed; width: 100%; }
.program-meta td { border: 1px solid #111; padding: 7px 9px; vertical-align: middle; width: 25%; }
.program-meta-label { color: #333; display: block; font-size: 9px; font-weight: 700; letter-spacing: .3px; margin-bottom: 2px; text-transform: uppercase; }
.program-meta-value { display: block; font-size: 12px; font-weight: 600; overflow-wrap: anywhere; }
.cloth-program-section { margin: 0 0 20px; page-break-inside: avoid; }
.cloth-program-item { font-size: 15px; font-weight: 700; margin: 0 0 3px; text-decoration: underline; }
.cloth-program-caption { color: #333; font-size: 11px; margin: 0 0 7px; }
.cloth-program-table { border-collapse: collapse; table-layout: auto; width: 100%; }
.cloth-program-table th, .cloth-program-table td { border: 1px solid #111; line-height: 1.2; padding: 5px 6px; vertical-align: middle; }
.cloth-program-table thead { display: table-header-group; }
.cloth-program-table thead th { background: #e7e7e7; font-size: 11px; font-weight: 700; text-align: center; }
.cloth-program-table .fabric-column { min-width: 105px; text-align: left; }
.cloth-program-table .dia-column { min-width: 145px; text-align: left; }
.cloth-program-table tbody td:first-child, .cloth-program-table tbody td:nth-child(2) { text-align: left; }
.cloth-program-table .weight { text-align: right; white-space: nowrap; }
.cloth-program-table .fabric-subtotal th { background: #f3f3f3; font-weight: 700; }
.cloth-program-table .fabric-subtotal .subtotal-label { text-align: left; }
.cloth-program-table tfoot th { background: #dedede; border-top: 2px solid #111; font-weight: 700; }
.cloth-program-table tfoot .grand-total-label { text-align: left; }
.program-summary { border-collapse: collapse; margin-top: 6px; table-layout: fixed; width: 100%; }
.program-summary td { background: #f3f3f3; border: 1px solid #111; padding: 8px 10px; text-align: center; width: 33.33%; }
.program-summary-label { display: block; font-size: 10px; font-weight: 600; margin-bottom: 2px; }
.program-summary-value { display: block; font-size: 14px; font-weight: 700; }
@media print { .cloth-program-section { page-break-inside: avoid; } }
